{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "In adult male ICR mice, intraperitoneal administration of mS-11 at 30 mg/kg produced a brain level of about 1 µg/g at 5 minutes with plasma about 4 µg/mL, directly demonstrating BBB crossing after systemic dosing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "In a mouse PK study, compound 40 crossed the blood-brain barrier and exhibited approximately 3 times the exposure in brain compared with plasma, indicating meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Dasatinib was detected at significant levels in the CSF of brain tumor patients, providing direct human evidence of CNS penetration after systemic administration.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Closest structural analogs with direct systemic CNS exposure data (mS-11, compound 40) support meaningful BBB penetration, and human CSF evidence for dasatinib is also positive. Negative imatinib/AM5144/SR144528 evidence is more distant or efflux-specific and does not override the closer positive analogs.",
  "evidence_gaps": [
    "No direct query-specific CNS exposure data; prediction is based on analogs with moderate Morgan similarity.",
    "Some positive human CSF evidence comes from brain tumor patients, where barrier integrity may be altered.",
    "Extensive negative imatinib-family data may reflect efflux-limited disposition not necessarily shared by the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

